import 'dart:typed_data';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

Future<Uint8List> buildDeliverySheet(PdfPageFormat format) async {
  final base = await PdfGoogleFonts.notoSansSCRegular(); // covers CJK + Latin
  final bold = await PdfGoogleFonts.notoSansSCBold();
  final doc = pw.Document(
    title: 'Deliveries',
    theme: pw.ThemeData.withFont(base: base, bold: bold, fontFallback: [base]),
  );
  doc.addPage(pw.MultiPage(
    pageFormat: PdfPageFormat.a4,
    build: (ctx) => [
      pw.Text('今日送货 / Penghantaran hari ini / Today\'s deliveries',
          style: pw.TextStyle(fontSize: 18, fontWeight: pw.FontWeight.bold)),
      pw.TableHelper.fromTextArray(
        headers: ['客户 Pelanggan', '数量 Qty'],
        data: [
          ['陈记 Kedai A', '3 ctn'],
        ],
      ),
    ],
  ));
  return doc.save();
}

Future<void> printSheet() async {
  final printed = await Printing.layoutPdf(
    onLayout: buildDeliverySheet,
    name: 'deliveries-2026-11-25',
    format: PdfPageFormat.a4,
  ); // false = cancelled
  final bytes = await buildDeliverySheet(PdfPageFormat.a4);
  await Printing.sharePdf(bytes: bytes, filename: 'deliveries-2026-11-25.pdf');
}

