import 'package:image_picker/image_picker.dart';

Future<Uint8List?> pickPhoto(bool camera) async {
  final XFile? f = await ImagePicker().pickImage(
    source: camera ? ImageSource.camera : ImageSource.gallery,
    maxWidth: 2000,
    maxHeight: 2000,
    imageQuality: 85,
    requestFullMetadata: false,
  );
  if (f == null) return null; // cancelled
  return f.readAsBytes(); // works on Android/iOS/web
}

import 'package:file_picker/file_picker.dart';

Future<(String, Uint8List)?> pickDoc() async {
  final PlatformFile? file = await FilePicker.pickFile(
    type: FileType.custom,
    allowedExtensions: const ['pdf', 'xlsx', 'xls', 'csv'],
  );
  if (file == null) return null; // cancelled
  final int? len = file.lengthSync() ?? await file.length();
  return (file.name, await file.readAsBytes()); // all platforms incl. web
}

