import 'package:url_launcher/url_launcher.dart';

/// digits: international, no '+', no leading 0, e.g. '60123456789'
Future<void> openWhatsApp(String digits, String text) async {
  final uri = Uri(
    scheme: 'https',
    host: 'wa.me',
    path: '/$digits',
    query: 'text=${Uri.encodeComponent(text)}', // %20 instead of '+'
  );
  // externalApplication: avoid Custom Tabs / SFSafariViewController so the WhatsApp app opens
  if (!await launchUrl(uri, mode: LaunchMode.externalApplication)) {
    // show error / copy text fallback
  }
}

